B64
tar xzf /tmp/gt.tgz -C /tmp/site && cp pipeline/hazards/common.py /tmp/code/ && ls /tmp/site/tiles/bld/14/*
curl -Ls https://micro.mamba.pm/api/micromamba/linux-64/latest | tar -xj -C /tmp bin/micromamba
export MAMBA_ROOT_PREFIX=/tmp/mamba; /tmp/bin/micromamba create -y -q -n pd -c conda-forge python=3.12 pdal python-pdal numpy matplotlib-base pillow > /dev/null 2>&1
PY=/tmp/mamba/envs/pd/bin/python; $PY -c "import pdal, matplotlib, PIL; print('env ok')"
cd /tmp && T0=$(date +%s)
$PY code/heights.py plan --site site --work work --shards 2 2>&1 | tail -20
$PY code/heights.py shard --site site --work work --shard 0 --deadline $(( $(date +%s) + 12 )) 2>&1 | grep -v "PDAL Error" | tail -4; echo "exit ${PIPESTATUS[0]}"
$PY code/heights.py shard --site site --work work --shard 0 --deadline $(( $(date +%s) + 600 )) 2>&1 | grep -v "PDAL Error" | tail -4; echo "exit ${PIPESTATUS[0]}"
$PY code/heights.py shard --site site --work work --shard 1 --deadline $(( $(date +%s) + 600 )) 2>&1 | grep -v "PDAL Error" | tail -4; echo "exit ${PIPESTATUS[0]}"
echo "shards $(( $(date +%s) - T0 )) s"
$PY code/heights.py merge --site site --work work --out /tmp/out 2>&1 | grep -E 'complete|measured|"osm"|median_abs' | head -12
cp -r /tmp/out/data/hazards/heights "$OUT/heights"; cp work/shard/*.npz "$OUT/" 2>/dev/null; ls -la "$OUT/heights"
date -u
